/* ==========================================================================
   Horizon University – Course Registration
   All text/background pairs meet WCAG 2.2 AA contrast (≥ 4.5:1).
   ========================================================================== */

:root {
  --ink: #1e1b3a;
  --ink-muted: #4b4868;
  --surface: #ffffff;
  --bg: #f6f5ff;
  --border: #d9d6f0;

  --primary: #4338ca;
  --primary-dark: #3730a3;
  --secondary: #be185d;
  --success: #15803d;
  --success-soft: #dcfce7;
  --danger: #b91c1c;
  --danger-soft: #fee2e2;
  --warning-soft: #fef3c7;

  --focus: #f59e0b;

  --gradient: linear-gradient(135deg, #4338ca 0%, #7e22ce 50%, #be185d 100%);

  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 4px 18px rgb(67 56 202 / 0.12);
  --shadow-lg: 0 12px 40px rgb(30 27 58 / 0.25);

  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --max-width: 1200px;
}

/* Department accent colors */
.accent-purple { --accent: #6d28d9; --accent-soft: #ede9fe; --accent-ink: #5b21b6; }
.accent-blue   { --accent: #1d4ed8; --accent-soft: #dbeafe; --accent-ink: #1e40af; }
.accent-green  { --accent: #15803d; --accent-soft: #dcfce7; --accent-ink: #166534; }
.accent-pink   { --accent: #be185d; --accent-soft: #fce7f3; --accent-ink: #9d174d; }
.accent-amber  { --accent: #b45309; --accent-soft: #fef3c7; --accent-ink: #92400e; }
.accent-teal   { --accent: #0f766e; --accent-soft: #ccfbf1; --accent-ink: #115e59; }

/* ---------- Base ---------- */
*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main { flex: 1; }

img, svg { max-width: 100%; }

h1, h2, h3 { line-height: 1.25; margin: 0 0 0.5em; }
h1 { font-size: clamp(1.9rem, 4vw + 1rem, 3rem); }
h2 { font-size: clamp(1.4rem, 2vw + 0.8rem, 2rem); }
h3 { font-size: 1.2rem; }

p { margin: 0 0 1em; }

a { color: var(--primary); text-underline-offset: 3px; }
a:hover { color: var(--secondary); }

/* Highly visible focus indicator for keyboard users */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

.section { padding-block: 3rem; }

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -100px;
  z-index: 1000;
  padding: 0.75rem 1.25rem;
  background: var(--ink);
  color: #fff;
  font-weight: 700;
  border-radius: var(--radius-sm);
  text-decoration: none;
}
.skip-link:focus { top: 1rem; color: #fff; }

/* ---------- Header / navigation ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--gradient);
  color: #fff;
  box-shadow: var(--shadow);
}

.nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 4.25rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: #fff;
  font-weight: 800;
  font-size: 1.2rem;
  text-decoration: none;
}
.brand:hover { color: #fff; }
.brand-logo {
  display: grid;
  place-items: center;
  width: 2.4rem; height: 2.4rem;
  border-radius: 50%;
  background: #fff;
  color: var(--primary);
  font-size: 1.3rem;
}

.nav-toggle {
  display: none;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 0.9rem;
  border: 2px solid #fff;
  border-radius: var(--radius-sm);
  background: transparent;
  color: #fff;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.nav-toggle-icon,
.nav-toggle-icon::before,
.nav-toggle-icon::after {
  display: block;
  width: 1.2rem; height: 2px;
  background: currentColor;
  border-radius: 2px;
  position: relative;
  transition: transform 0.2s ease;
}
.nav-toggle-icon::before, .nav-toggle-icon::after { content: ""; position: absolute; left: 0; }
.nav-toggle-icon::before { top: -6px; }
.nav-toggle-icon::after  { top: 6px; }
.nav-toggle[aria-expanded="true"] .nav-toggle-icon { background: transparent; }
.nav-toggle[aria-expanded="true"] .nav-toggle-icon::before { transform: translateY(6px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] .nav-toggle-icon::after  { transform: translateY(-6px) rotate(-45deg); }

.nav-list {
  display: flex;
  gap: 0.35rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav-list a {
  display: block;
  padding: 0.55rem 1rem;
  border-radius: 999px;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  transition: background-color 0.2s ease;
}
.nav-list a:hover { background: rgb(255 255 255 / 0.18); color: #fff; }
.nav-list a[aria-current="page"] {
  background: #fff;
  color: var(--primary-dark);
}
.nav-badge {
  display: inline-grid;
  place-items: center;
  min-width: 1.4rem;
  height: 1.4rem;
  margin-left: 0.35rem;
  padding: 0 0.35rem;
  border-radius: 999px;
  background: #fde047;
  color: #1e1b3a;
  font-size: 0.8rem;
  font-weight: 800;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 44px;           /* WCAG target size */
  padding: 0.6rem 1.25rem;
  border: 2px solid transparent;
  border-radius: 999px;
  font: inherit;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}
.btn:hover { transform: translateY(-1px); box-shadow: var(--shadow); }
.btn:disabled, .btn[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.65;
  transform: none;
  box-shadow: none;
}

.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); color: #fff; }

.btn-secondary { background: var(--secondary); color: #fff; }
.btn-secondary:hover { background: #9d174d; color: #fff; }

.btn-outline { background: var(--surface); border-color: var(--primary); color: var(--primary); }
.btn-outline:hover { background: #eef2ff; color: var(--primary-dark); }

.btn-light { background: #fff; color: var(--primary-dark); }
.btn-light:hover { background: #fde047; color: var(--ink); }

.btn-ghost-light { background: transparent; border-color: #fff; color: #fff; }
.btn-ghost-light:hover { background: rgb(255 255 255 / 0.15); color: #fff; }

.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover { background: #991b1b; color: #fff; }

.btn-sm { min-height: 36px; padding: 0.35rem 0.9rem; font-size: 0.9rem; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  padding-block: 4.5rem 5rem;
  background: var(--gradient);
  color: #fff;
}
.hero::before, .hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  opacity: 0.25;
  pointer-events: none;
}
.hero::before { width: 420px; height: 420px; background: #fde047; top: -160px; right: -120px; }
.hero::after  { width: 300px; height: 300px; background: #22d3ee; bottom: -150px; left: -80px; }
.hero .container { position: relative; z-index: 1; }
.hero-eyebrow {
  display: inline-block;
  padding: 0.3rem 0.9rem;
  margin-bottom: 1rem;
  border-radius: 999px;
  background: rgb(255 255 255 / 0.2);
  font-weight: 700;
  letter-spacing: 0.03em;
}
.hero p.lead { font-size: 1.2rem; max-width: 40rem; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 1.5rem; }

.hero-search {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  max-width: 38rem;
  margin-top: 1.75rem;
  padding: 0.5rem;
  border-radius: 999px;
  background: #fff;
  box-shadow: var(--shadow-lg);
}
.hero-search label { flex-basis: 100%; }
.hero-search input {
  flex: 1;
  min-width: 0;
  min-height: 44px;
  padding: 0 1rem;
  border: 0;
  border-radius: 999px;
  font: inherit;
  color: var(--ink);
  background: transparent;
}

.page-hero {
  padding-block: 2.5rem;
  background: var(--gradient);
  color: #fff;
}
.page-hero p { margin: 0; font-size: 1.1rem; max-width: 46rem; }

/* ---------- Stats ---------- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-top: -3rem;
  position: relative;
  z-index: 2;
}
.stat-card {
  padding: 1.25rem 1.5rem;
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  border-top: 6px solid var(--accent, var(--primary));
}
.stat-value { display: block; font-size: 2rem; font-weight: 800; color: var(--accent-ink, var(--primary)); }
.stat-label { color: var(--ink-muted); font-weight: 600; }

/* ---------- Generic cards & grids ---------- */
.grid {
  display: grid;
  gap: 1.25rem;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr));
}

.card {
  padding: 1.5rem;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}

.section-header {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.section-header p { margin: 0; color: var(--ink-muted); }

/* Department tiles on home page */
.dept-tile {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: var(--accent-soft);
  color: var(--accent-ink);
  font-weight: 700;
  text-decoration: none;
  border: 2px solid transparent;
  transition: transform 0.15s ease, border-color 0.15s ease;
}
.dept-tile:hover { transform: translateY(-3px); border-color: var(--accent); color: var(--accent-ink); }
.dept-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 3rem; height: 3rem;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font-size: 1.4rem;
}
.dept-count { display: block; font-weight: 500; font-size: 0.9rem; }

/* Steps */
.steps { counter-reset: step; list-style: none; padding: 0; margin: 0; }
.steps li { counter-increment: step; position: relative; padding-left: 4rem; }
.steps li::before {
  content: counter(step);
  position: absolute;
  left: 1.5rem; top: 1.4rem;
  display: grid;
  place-items: center;
  width: 2.25rem; height: 2.25rem;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-weight: 800;
}
.steps li.card { padding-left: 4.75rem; }

/* Deadlines list */
.deadline-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.75rem; }
.deadline-list li {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.9rem 1.1rem;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  border-left: 6px solid var(--accent);
}
.deadline-list time { font-weight: 800; color: var(--accent-ink); min-width: 5.5rem; }

/* ---------- Catalog filters ---------- */
.filters {
  display: grid;
  gap: 1rem;
  grid-template-columns: 2fr repeat(3, 1fr);
  align-items: end;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.filters-footer {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.results-count {
  margin: 0 0 1rem;
  font-weight: 700;
  color: var(--ink-muted);
}

/* ---------- Course cards ---------- */
.course-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.course-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.course-card-header {
  padding: 1.1rem 1.25rem;
  background: var(--accent);
  color: #fff;
}
.course-card-header h3 { margin: 0.25rem 0 0; font-size: 1.15rem; }
.course-code {
  display: inline-block;
  padding: 0.1rem 0.6rem;
  border-radius: 999px;
  background: rgb(255 255 255 / 0.22);
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.course-card-body { flex: 1; padding: 1.25rem; }
.course-card-body p { color: var(--ink-muted); }

.course-meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.3rem 0.75rem;
  margin: 0;
  font-size: 0.95rem;
}
.course-meta dt { font-weight: 700; color: var(--accent-ink); }
.course-meta dd { margin: 0; }

.seat-bar {
  height: 10px;
  margin-top: 1rem;
  border-radius: 999px;
  background: var(--accent-soft);
  overflow: hidden;
}
.seat-bar-fill { height: 100%; border-radius: inherit; background: var(--accent); }
.seat-text { margin: 0.4rem 0 0; font-size: 0.9rem; font-weight: 600; }

.course-card-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--border);
  background: #fbfaff;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem 0.7rem;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 700;
}
.tag-success { background: var(--success-soft); color: #166534; }
.tag-danger  { background: var(--danger-soft);  color: #991b1b; }
.tag-accent  { background: var(--accent-soft);  color: var(--accent-ink); }

.empty-state {
  padding: 3rem 1.5rem;
  text-align: center;
  border: 3px dashed var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}
.empty-state-icon { font-size: 2.5rem; }

/* ---------- Forms ---------- */
.form-grid {
  display: grid;
  gap: 1.25rem;
  grid-template-columns: repeat(2, 1fr);
}
.form-grid .full { grid-column: 1 / -1; }

.field { display: flex; flex-direction: column; gap: 0.35rem; }

label, legend { font-weight: 700; }
.required { color: var(--danger); }
.hint { font-size: 0.9rem; color: var(--ink-muted); }

input[type="text"], input[type="email"], input[type="search"], select, textarea {
  width: 100%;
  min-height: 44px;
  padding: 0.6rem 0.85rem;
  border: 2px solid #8e8ab0;      /* 3:1 non-text contrast */
  border-radius: var(--radius-sm);
  background: #fff;
  font: inherit;
  color: var(--ink);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
input:hover, select:hover, textarea:hover { border-color: var(--primary); }
input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
  border-color: var(--primary);
}
textarea { min-height: 6rem; resize: vertical; }

[aria-invalid="true"] { border-color: var(--danger) !important; background: #fff7f7; }

.error-message {
  display: flex;
  gap: 0.35rem;
  margin: 0;
  color: var(--danger);
  font-size: 0.92rem;
  font-weight: 600;
}
.error-message:empty { display: none; }
.error-message::before { content: "⚠"; }

fieldset {
  margin: 0;
  padding: 1rem 1.25rem 1.25rem;
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
}
legend { padding: 0 0.4rem; }

.choice-group { display: flex; flex-wrap: wrap; gap: 0.75rem; }
.choice {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.4rem 1rem;
  border: 2px solid var(--border);
  border-radius: 999px;
  font-weight: 600;
  cursor: pointer;
}
.choice:has(input:checked) { border-color: var(--primary); background: #eef2ff; color: var(--primary-dark); }
.choice input, .checkbox input { width: 1.2rem; height: 1.2rem; accent-color: var(--primary); }
.checkbox { display: inline-flex; align-items: flex-start; gap: 0.6rem; font-weight: 600; cursor: pointer; }
.checkbox input { margin-top: 0.2rem; flex-shrink: 0; }

.form-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 1.5rem; }

/* Course preview inside registration form */
.course-preview {
  padding: 1rem 1.25rem;
  border-radius: var(--radius-sm);
  background: var(--accent-soft, #eef2ff);
  border-left: 6px solid var(--accent, var(--primary));
}
.course-preview:empty { display: none; }
.course-preview h3 { color: var(--accent-ink, var(--primary-dark)); margin-bottom: 0.25rem; }
.course-preview p { margin: 0; }

/* ---------- Alerts ---------- */
.alert {
  display: flex;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  margin-bottom: 1.5rem;
  border-radius: var(--radius-sm);
  border-left: 6px solid;
}
.alert[hidden] { display: none; }
.alert h2, .alert h3 { font-size: 1.1rem; margin-bottom: 0.35rem; }
.alert ul { margin: 0; padding-left: 1.2rem; }
.alert p:last-child { margin: 0; }
.alert-error   { background: var(--danger-soft);  border-color: var(--danger);  color: #7f1d1d; }
.alert-error a { color: #7f1d1d; font-weight: 700; }
.alert-success { background: var(--success-soft); border-color: var(--success); color: #14532d; }
.alert-success a { color: #14532d; font-weight: 700; }

/* ---------- Layout: two columns ---------- */
.layout-2col {
  display: grid;
  gap: 2rem;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  align-items: start;
}

/* ---------- Data table ---------- */
.table-wrapper {
  overflow-x: auto;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--shadow);
}
.data-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
}
.data-table caption {
  padding: 1rem 1.25rem;
  text-align: left;
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--primary-dark);
  caption-side: top;
}
.data-table th, .data-table td {
  padding: 0.85rem 1rem;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid var(--border);
}
.data-table thead th {
  background: var(--primary);
  color: #fff;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.data-table tbody tr:nth-child(even) { background: #f8f7ff; }
.data-table tbody tr:hover { background: #eef2ff; }
.data-table tfoot td, .data-table tfoot th { font-weight: 800; background: #fef9c3; }
.data-table .num { text-align: right; }
.data-table .empty-row td { padding: 2rem; text-align: center; color: var(--ink-muted); }

/* ---------- Modal (native <dialog>) ---------- */
.modal {
  width: min(92vw, 520px);
  padding: 0;
  border: 0;
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  color: var(--ink);
}
.modal::backdrop { background: rgb(30 27 58 / 0.6); backdrop-filter: blur(3px); }
.modal[open] { animation: modal-in 0.2s ease-out; }
@keyframes modal-in {
  from { opacity: 0; transform: translateY(16px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.5rem;
  background: var(--gradient);
  color: #fff;
}
.modal-header.danger { background: linear-gradient(135deg, #b91c1c, #be185d); }
.modal-header h2 { margin: 0; font-size: 1.3rem; }
.modal-close {
  display: grid;
  place-items: center;
  width: 44px; height: 44px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: transparent;
  color: #fff;
  font-size: 1.5rem;
  line-height: 1;
  cursor: pointer;
}
.modal-close:hover { background: rgb(255 255 255 / 0.2); }
.modal-body { padding: 1.5rem; }
.modal-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1rem 1.5rem 1.5rem;
}
.summary-list {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.5rem 1rem;
  margin: 1rem 0 0;
  padding: 1rem;
  border-radius: var(--radius-sm);
  background: #f8f7ff;
}
.summary-list dt { font-weight: 700; color: var(--primary-dark); }
.summary-list dd { margin: 0; }

/* ---------- Profile ---------- */
.profile-card { text-align: center; }
.avatar {
  display: grid;
  place-items: center;
  width: 7rem; height: 7rem;
  margin: 0 auto 1rem;
  border-radius: 50%;
  background: var(--gradient);
  color: #fff;
  font-size: 2.5rem;
  font-weight: 800;
  border: 5px solid #fde047;
}
.profile-details {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.5rem 1rem;
  margin: 1.25rem 0 0;
  text-align: left;
}
.profile-details dt { font-weight: 700; color: var(--primary-dark); }
.profile-details dd { margin: 0; overflow-wrap: anywhere; }

.progress-wrap { margin-top: 1.5rem; text-align: left; }
.progress {
  width: 100%;
  height: 14px;
  appearance: none;
  border: 0;
  border-radius: 999px;
  background: #e0e7ff;
  overflow: hidden;
}
.progress::-webkit-progress-bar { background: #e0e7ff; border-radius: 999px; }
.progress::-webkit-progress-value { background: var(--gradient); border-radius: 999px; }
.progress::-moz-progress-bar { background: var(--gradient); border-radius: 999px; }

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 3rem;
  padding-block: 2rem;
  background: var(--ink);
  color: #e6e4f5;
}
.site-footer a { color: #fde047; }
.site-footer a:hover { color: #fff; }
.footer-inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
}
.footer-inner p { margin: 0; }
.footer-links { display: flex; flex-wrap: wrap; gap: 1.25rem; list-style: none; margin: 0; padding: 0; }

/* ---------- Responsive ---------- */
@media (max-width: 960px) {
  .filters { grid-template-columns: repeat(2, 1fr); }
  .filters .field-search { grid-column: 1 / -1; }
  .layout-2col { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .nav-toggle { display: inline-flex; }
  .nav-menu {
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    padding: 0.75rem 1.25rem 1.25rem;
    background: #3730a3;
    box-shadow: var(--shadow-lg);
  }
  /* Menu is hidden only when JS has enhanced the toggle; without JS it stays visible */
  .js .nav-menu[data-open="false"] { display: none; }
  .nav-list { flex-direction: column; }
  .nav-list a { padding: 0.8rem 1rem; border-radius: var(--radius-sm); }
  .no-js .nav-toggle { display: none; }
  .no-js .nav-menu { position: static; background: transparent; box-shadow: none; padding: 0 0 1rem; }
  .no-js .nav-bar { flex-wrap: wrap; }

  .form-grid { grid-template-columns: 1fr; }
  .hero { padding-block: 3rem 4.5rem; }
  .hero-search { border-radius: var(--radius); }
  .hero-search .btn { width: 100%; }
  .section { padding-block: 2rem; }
}

@media (max-width: 520px) {
  .filters { grid-template-columns: 1fr; }
  .modal-footer .btn { width: 100%; }
  .form-actions .btn { width: 100%; }
}

/* ---------- User preferences ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (forced-colors: active) {
  .btn, .nav-list a, .choice, .tag, .modal-close { border: 2px solid ButtonText; }
  .nav-list a[aria-current="page"] { outline: 2px solid Highlight; }
}

@media print {
  .site-header, .site-footer, .btn, .filters { display: none !important; }
  body { background: #fff; }
}

input.content:
/* Horizon University – Course Registration
   Shared helpers plus page-specific initialisers (selected via <body data-page>). */
"use strict";

/* ==========================================================================
   Storage
   ========================================================================== */
const Store = {
  REG_KEY: "hu.registrations",
  PROFILE_KEY: "hu.profile",

  read(key, fallback) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  },
  write(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      /* Storage unavailable (private mode etc.) – app still works for this page view. */
    }
  },

  getRegistrations() { return this.read(this.REG_KEY, []); },
  setRegistrations(list) { this.write(this.REG_KEY, list); },

  getProfile() {
    return this.read(this.PROFILE_KEY, {
      name: "Jordan Lee",
      studentId: "S2024817",
      email: "jordan.lee@horizon.edu",
      major: "Computer Science",
      year: "Sophomore",
    });
  },
  setProfile(profile) { this.write(this.PROFILE_KEY, profile); },
};

/* ==========================================================================
   Utilities
   ========================================================================== */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

function escapeHTML(value) {
  return String(value).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[c]);
}

function findCourse(code) {
  return COURSES.find((c) => c.code === code);
}

function formatCode(code) {
  // "CS101" -> "CS 101" (easier for screen readers and humans)
  return code.replace(/^([A-Z]+)(\d+)$/, "$1 $2");
}

function formatTime(t) {
  const [h, m] = t.split(":").map(Number);
  const suffix = h >= 12 ? "PM" : "AM";
  return `${((h + 11) % 12) + 1}:${String(m).padStart(2, "0")} ${suffix}`;
}

function formatSchedule(course) {
  return `${course.days.join(", ")} · ${formatTime(course.start)}–${formatTime(course.end)}`;
}

function toMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function coursesOverlap(a, b) {
  const sharedDay = a.days.some((d) => b.days.includes(d));
  return sharedDay && toMinutes(a.start) < toMinutes(b.end) && toMinutes(b.start) < toMinutes(a.end);
}

function isRegistered(code) {
  return Store.getRegistrations().some((r) => r.code === code);
}

function seatsLeft(course) {
  return Math.max(0, course.capacity - course.enrolled - (isRegistered(course.code) ? 1 : 0));
}

function totalCredits(registrations = Store.getRegistrations()) {
  return registrations.reduce((sum, r) => sum + (findCourse(r.code)?.credits ?? 0), 0);
}

function deptColor(dept) {
  return DEPARTMENTS[dept]?.color ?? "purple";
}

/* Screen-reader announcements via a shared polite live region. */
function announce(message) {
  const region = $("#live-region");
  if (!region) return;
  region.textContent = "";
  // Small delay so repeated identical messages are still announced.
  setTimeout(() => { region.textContent = message; }, 50);
}

/* ==========================================================================
   Navigation
   ========================================================================== */
function initNav() {
  const toggle = $(".nav-toggle");
  const menu = $("#primary-menu");
  if (!toggle || !menu) return;

  const setOpen = (open) => {
    toggle.setAttribute("aria-expanded", String(open));
    menu.dataset.open = String(open);
  };
  setOpen(false);

  toggle.addEventListener("click", () => {
    setOpen(toggle.getAttribute("aria-expanded") !== "true");
  });

  // Close on Escape and return focus to the toggle
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && toggle.getAttribute("aria-expanded") === "true") {
      setOpen(false);
      toggle.focus();
    }
  });

  // Close when focus/click leaves the header on small screens
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".site-header")) setOpen(false);
  });

  updateNavBadge();
}

function updateNavBadge() {
  const badge = $("#nav-reg-count");
  if (!badge) return;
  const count = Store.getRegistrations().length;
  badge.textContent = count;
  badge.hidden = count === 0;
  $("#nav-reg-count-label").textContent = count ? `, ${count} registered course${count === 1 ? "" : "s"}` : "";
}

/* ==========================================================================
   Confirmation modal (native <dialog> provides focus containment,
   Escape-to-close and an inert background).
   ========================================================================== */
const Modal = {
  dialog: null,
  opener: null,
  onConfirm: null,

  init() {
    this.dialog = $("#confirm-modal");
    if (!this.dialog) return;

    $("#modal-confirm", this.dialog).addEventListener("click", () => {
      const cb = this.onConfirm;
      this.close();
      if (cb) cb();
    });
    $$("[data-modal-close]", this.dialog).forEach((btn) =>
      btn.addEventListener("click", () => this.close())
    );
    // Click on backdrop closes
    this.dialog.addEventListener("click", (e) => {
      if (e.target === this.dialog) this.close();
    });
    // Restore focus to whatever opened the dialog
    this.dialog.addEventListener("close", () => {
      if (this.opener && document.contains(this.opener)) this.opener.focus();
      this.opener = null;
    });
  },

  open({ title, body, confirmText = "Confirm", cancelText = "Cancel", danger = false, onConfirm }) {
    if (!this.dialog) return;
    this.opener = document.activeElement;
    this.onConfirm = onConfirm;

    $("#modal-title", this.dialog).textContent = title;
    $("#modal-body", this.dialog).innerHTML = body;
    const confirmBtn = $("#modal-confirm", this.dialog);
    confirmBtn.textContent = confirmText;
    confirmBtn.className = `btn ${danger ? "btn-danger" : "btn-primary"}`;
    $("#modal-cancel", this.dialog).textContent = cancelText;
    $(".modal-header", this.dialog).classList.toggle("danger", danger);

    this.dialog.showModal();
    // Focus the least destructive action by default
    $("#modal-cancel", this.dialog).focus();
  },

  close() {
    this.onConfirm = null;
    if (this.dialog?.open) this.dialog.close();
  },
};

/* ==========================================================================
   Course card
   ========================================================================== */
function courseCardHTML(course) {
  const dept = DEPARTMENTS[course.dept];
  const left = seatsLeft(course);
  const registered = isRegistered(course.code);
  const pctFull = Math.round(((course.capacity - left) / course.capacity) * 100);
  const headingId = `course-${course.code}-title`;

  let status;
  let action;
  if (registered) {
    status = `<span class="tag tag-success"><span aria-hidden="true">✓</span> Registered</span>`;
    action = `<a class="btn btn-outline btn-sm" href="profile.html">View schedule</a>`;
  } else if (left === 0) {
    status = `<span class="tag tag-danger"><span aria-hidden="true">✕</span> Full</span>`;
    action = `<button type="button" class="btn btn-outline btn-sm" disabled>Class full</button>`;
  } else {
    status = `<span class="tag tag-accent">${left} seat${left === 1 ? "" : "s"} open</span>`;
    action = `<a class="btn btn-primary btn-sm" href="register.html?course=${course.code}"
                 aria-describedby="${headingId}">Register</a>`;
  }

  return `
    <li class="course-card accent-${dept.color}">
      <article aria-labelledby="${headingId}">
        <div class="course-card-header">
          <span class="course-code">${formatCode(course.code)}</span>
          <h3 id="${headingId}">${escapeHTML(course.title)}</h3>
        </div>
        <div class="course-card-body">
          <p>${escapeHTML(course.description)}</p>
          <dl class="course-meta">
            <dt>Department</dt><dd>${escapeHTML(dept.name)}</dd>
            <dt>Instructor</dt><dd>${escapeHTML(course.instructor)}</dd>
            <dt>Schedule</dt><dd>${formatSchedule(course)}</dd>
            <dt>Room</dt><dd>${escapeHTML(course.room)}</dd>
            <dt>Credits</dt><dd>${course.credits}</dd>
          </dl>
          <div class="seat-bar" aria-hidden="true">
            <div class="seat-bar-fill" style="width:${pctFull}%"></div>
          </div>
          <p class="seat-text">${left} of ${course.capacity} seats available</p>
        </div>
        <div class="course-card-footer">
          ${status}
          ${action}
        </div>
      </article>
    </li>`;
}

/* ==========================================================================
   Registered courses table (used on Registration and Profile pages)
   ========================================================================== */
function renderRegistrationsTable() {
  const tbody = $("#registered-tbody");
  if (!tbody) return;
  const regs = Store.getRegistrations();
  const tfoot = $("#registered-tfoot");

  if (regs.length === 0) {
    tbody.innerHTML = `
      <tr class="empty-row">
        <td colspan="8">You haven't registered for any courses yet.
          <a href="catalog.html">Browse the course catalog</a>.</td>
      </tr>`;
    if (tfoot) tfoot.innerHTML = "";
  } else {
    tbody.innerHTML = regs.map((r) => {
      const c = findCourse(r.code);
      if (!c) return "";
      return `
        <tr>
          <th scope="row">${formatCode(c.code)}</th>
          <td>${escapeHTML(c.title)}</td>
          <td class="num">${c.credits}</td>
          <td>${formatSchedule(c)}</td>
          <td>${escapeHTML(c.instructor)}</td>
          <td>${escapeHTML(r.term)}</td>
          <td>${escapeHTML(r.grading)}</td>
          <td>
            <button type="button" class="btn btn-danger btn-sm" data-drop="${c.code}">
              Drop<span class="visually-hidden"> ${formatCode(c.code)}, ${escapeHTML(c.title)}</span>
            </button>
          </td>
        </tr>`;
    }).join("");
    if (tfoot) {
      tfoot.innerHTML = `
        <tr>
          <th scope="row" colspan="2">Total credits</th>
          <td class="num">${totalCredits(regs)}</td>
          <td colspan="5">of ${MAX_CREDITS} maximum this term</td>
        </tr>`;
    }
  }
}

function initDropButtons(onChange) {
  const tbody = $("#registered-tbody");
  if (!tbody) return;

  tbody.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-drop]");
    if (!btn) return;
    const course = findCourse(btn.dataset.drop);

    Modal.open({
      title: "Drop this course?",
      body: `<p>Are you sure you want to drop <strong>${formatCode(course.code)}: ${escapeHTML(course.title)}</strong>?
             Your seat will be released to other students.</p>`,
      confirmText: "Yes, drop course",
      cancelText: "Keep course",
      danger: true,
      onConfirm: () => {
        Store.setRegistrations(Store.getRegistrations().filter((r) => r.code !== course.code));
        renderRegistrationsTable();
        updateNavBadge();
        if (onChange) onChange();
        announce(`${formatCode(course.code)} ${course.title} was dropped.`);
        // The button that opened the modal no longer exists; move focus somewhere sensible.
        const heading = $("#registered-heading");
        heading?.focus();
      },
    });
  });
}

/* ==========================================================================
   Page: Home
   ========================================================================== */
function initHome() {
  const deptGrid = $("#dept-grid");
  if (deptGrid) {
    deptGrid.innerHTML = Object.entries(DEPARTMENTS).map(([code, d]) => {
      const count = COURSES.filter((c) => c.dept === code).length;
      return `
        <li>
          <a class="dept-tile accent-${d.color}" href="catalog.html?dept=${code}">
            <span class="dept-icon" aria-hidden="true">${deptIcon(code)}</span>
            <span>${escapeHTML(d.name)}
              <span class="dept-count">${count} course${count === 1 ? "" : "s"}</span>
            </span>
          </a>
        </li>`;
    }).join("");
  }

  const stat = (id, value) => { const el = $(id); if (el) el.textContent = value; };
  stat("#stat-courses", COURSES.length);
  stat("#stat-depts", Object.keys(DEPARTMENTS).length);
  stat("#stat-open", COURSES.reduce((sum, c) => sum + seatsLeft(c), 0));
  stat("#stat-mine", Store.getRegistrations().length);

  const featured = $("#featured-courses");
  if (featured) {
    featured.innerHTML = COURSES.filter((c) => seatsLeft(c) > 0).slice(0, 3).map(courseCardHTML).join("");
  }
}

function deptIcon(code) {
  return { CS: "💻", MATH: "∑", BIO: "🧬", ART: "🎨", HIST: "🏛", PSY: "🧠" }[code] ?? "📘";
}

/* ==========================================================================
   Page: Catalog
   ========================================================================== */
function initCatalog() {
  const form = $("#filter-form");
  const search = $("#search");
  const deptSel = $("#filter-dept");
  const levelSel = $("#filter-level");
  const creditSel = $("#filter-credits");
  const openOnly = $("#filter-open");
  const list = $("#course-list");
  const count = $("#results-count");

  // Populate dropdowns from data
  deptSel.insertAdjacentHTML("beforeend", Object.entries(DEPARTMENTS)
    .map(([code, d]) => `<option value="${code}">${escapeHTML(d.name)}</option>`).join(""));
  levelSel.insertAdjacentHTML("beforeend", Object.entries(LEVELS)
    .map(([lvl, label]) => `<option value="${lvl}">${escapeHTML(label)}</option>`).join(""));
  const credits = [...new Set(COURSES.map((c) => c.credits))].sort();
  creditSel.insertAdjacentHTML("beforeend", credits
    .map((n) => `<option value="${n}">${n} credits</option>`).join(""));

  // Restore state from URL (?q=…&dept=…) so filtered views are linkable
  const params = new URLSearchParams(location.search);
  search.value = params.get("q") ?? "";
  deptSel.value = DEPARTMENTS[params.get("dept")] ? params.get("dept") : "";
  levelSel.value = LEVELS[params.get("level")] ? params.get("level") : "";
  creditSel.value = credits.includes(Number(params.get("credits"))) ? params.get("credits") : "";
  openOnly.checked = params.get("open") === "1";

  function apply({ announceResult = true } = {}) {
    const q = search.value.trim().toLowerCase();
    const results = COURSES.filter((c) => {
      const haystack = [c.code, formatCode(c.code), c.title, c.instructor, c.description,
                        DEPARTMENTS[c.dept].name].join(" ").toLowerCase();
      return (!q || haystack.includes(q))
        && (!deptSel.value || c.dept === deptSel.value)
        && (!levelSel.value || c.level === Number(levelSel.value))
        && (!creditSel.value || c.credits === Number(creditSel.value))
        && (!openOnly.checked || seatsLeft(c) > 0);
    });

    if (results.length) {
      list.innerHTML = results.map(courseCardHTML).join("");
      list.hidden = false;
      $("#no-results").hidden = true;
    } else {
      list.innerHTML = "";
      list.hidden = true;
      $("#no-results").hidden = false;
    }

    const msg = `Showing ${results.length} of ${COURSES.length} courses`;
    count.textContent = msg;
    if (announceResult) announce(msg);

    // Keep the URL in sync without adding history entries
    const next = new URLSearchParams();
    if (search.value.trim()) next.set("q", search.value.trim());
    if (deptSel.value) next.set("dept", deptSel.value);
    if (levelSel.value) next.set("level", levelSel.value);
    if (creditSel.value) next.set("credits", creditSel.value);
    if (openOnly.checked) next.set("open", "1");
    const qs = next.toString();
    history.replaceState(null, "", qs ? `?${qs}` : location.pathname);
  }

  // Debounce typing so screen readers aren't flooded with announcements
  let timer;
  search.addEventListener("input", () => {
    clearTimeout(timer);
    timer = setTimeout(apply, 350);
  });
  [deptSel, levelSel, creditSel, openOnly].forEach((el) => el.addEventListener("change", () => apply()));

  form.addEventListener("submit", (e) => { e.preventDefault(); clearTimeout(timer); apply(); });
  form.addEventListener("reset", () => {
    // Wait for the browser to reset the controls before filtering
    setTimeout(() => { apply(); search.focus(); }, 0);
  });
  $("#clear-filters")?.addEventListener("click", () => form.reset());

  apply({ announceResult: false });
}

/* ==========================================================================
   Page: Registration
   ========================================================================== */
function initRegister() {
  const form = $("#registration-form");
  const courseSel = $("#reg-course");
  const termSel = $("#reg-term");
  const preview = $("#course-preview");
  const summary = $("#error-summary");
  const success = $("#success-message");

  // Populate selects
  termSel.insertAdjacentHTML("beforeend",
    TERMS.map((t) => `<option value="${t}">${t}</option>`).join(""));

  function populateCourses() {
    const current = courseSel.value;
    courseSel.innerHTML = `<option value="">Select a course…</option>` +
      Object.entries(DEPARTMENTS).map(([code, d]) => {
        const options = COURSES.filter((c) => c.dept === code).map((c) => {
          const left = seatsLeft(c);
          const registered = isRegistered(c.code);
          const note = registered ? " (already registered)" : left === 0 ? " (full)" : ` (${left} seats)`;
          return `<option value="${c.code}" ${registered || left === 0 ? "disabled" : ""}>
                    ${formatCode(c.code)} – ${escapeHTML(c.title)}${note}</option>`;
        }).join("");
        return `<optgroup label="${escapeHTML(d.name)}">${options}</optgroup>`;
      }).join("");
    const opt = $(`option[value="${current}"]`, courseSel);
    courseSel.value = opt && !opt.disabled ? current : "";
  }
  populateCourses();

  // Prefill from profile
  const profile = Store.getProfile();
  $("#reg-name").value = profile.name;
  $("#reg-id").value = profile.studentId;
  $("#reg-email").value = profile.email;
  termSel.value = TERMS[0];

  // Preselect course from ?course=
  const requested = new URLSearchParams(location.search).get("course");
  if (requested) {
    const opt = $(`option[value="${CSS.escape(requested)}"]`, courseSel);
    if (opt && !opt.disabled) courseSel.value = requested;
  }

  function updatePreview() {
    const c = findCourse(courseSel.value);
    preview.className = "course-preview";
    if (!c) { preview.innerHTML = ""; return; }
    preview.classList.add(`accent-${deptColor(c.dept)}`);
    preview.innerHTML = `
      <h3>${formatCode(c.code)}: ${escapeHTML(c.title)}</h3>
      <p>${formatSchedule(c)} · ${escapeHTML(c.room)}</p>
      <p>${escapeHTML(c.instructor)} · ${c.credits} credits · ${seatsLeft(c)} seats left</p>`;
  }
  courseSel.addEventListener("change", updatePreview);
  updatePreview();

  /* ---- Validation ---- */
  const validators = {
    "reg-name": (v) => v.trim().length >= 2 || "Enter your full name.",
    "reg-id": (v) => /^S\d{7}$/i.test(v.trim()) || "Enter a student ID in the format S followed by 7 digits, for example S2024817.",
    "reg-email": (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()) || "Enter a valid email address, for example name@horizon.edu.",
    "reg-term": (v) => !!v || "Select a term.",
    "reg-course": (v) => {
      if (!v) return "Select a course to register for.";
      const c = findCourse(v);
      const regs = Store.getRegistrations();
      if (regs.some((r) => r.code === v)) return "You are already registered for this course.";
      if (seatsLeft(c) === 0) return "This course is full. Choose another course.";
      if (totalCredits(regs) + c.credits > MAX_CREDITS) {
        return `Adding this course would exceed the ${MAX_CREDITS}-credit limit (you have ${totalCredits(regs)} credits).`;
      }
      const clash = regs.map((r) => findCourse(r.code)).find((other) => other && coursesOverlap(c, other));
      if (clash) return `This course conflicts with ${formatCode(clash.code)} (${formatSchedule(clash)}).`;
      return true;
    },
    "reg-grading": () => !!$("input[name='grading']:checked", form) || "Choose a grading option.",
    "reg-agree": () => $("#reg-agree").checked || "You must confirm that you have read the registration policy.",
  };

  function setFieldError(id, message) {
    const errorEl = $(`#${id}-error`);
    const field = id === "reg-grading" ? $("#reg-grading") : $(`#${id}`);
    if (message) {
      errorEl.textContent = message;
      if (id === "reg-grading") {
        $$("input[name='grading']", form).forEach((r) => r.setAttribute("aria-invalid", "true"));
      } else {
        field.setAttribute("aria-invalid", "true");
      }
    } else {
      errorEl.textContent = "";
      if (id === "reg-grading") {
        $$("input[name='grading']", form).forEach((r) => r.removeAttribute("aria-invalid"));
      } else {
        field.removeAttribute("aria-invalid");
      }
    }
  }

  function validateField(id) {
    const el = $(`#${id}`);
    const result = validators[id](el?.value ?? "");
    const message = result === true ? "" : result;
    setFieldError(id, message);
    return message;
  }

  // Re-validate fields once the user has interacted and they were invalid
  Object.keys(validators).forEach((id) => {
    const targets = id === "reg-grading" ? $$("input[name='grading']", form) : [$(`#${id}`)];
    targets.forEach((el) => {
      const evt = el.type === "checkbox" || el.type === "radio" || el.tagName === "SELECT" ? "change" : "blur";
      el.addEventListener(evt, () => {
        if ($(`#${id}-error`).textContent) validateField(id);
      });
    });
  });

  function focusTargetFor(id) {
    return id === "reg-grading" ? $("input[name='grading']", form) : $(`#${id}`);
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    success.hidden = true;

    const errors = Object.keys(validators)
      .map((id) => ({ id, message: validateField(id) }))
      .filter((r) => r.message);

    if (errors.length) {
      summary.innerHTML = `
        <div>
          <h2 id="error-summary-title">There ${errors.length === 1 ? "is 1 problem" : `are ${errors.length} problems`} with your registration</h2>
          <ul>${errors.map((err) => `<li><a href="#${err.id}" data-focus="${err.id}">${escapeHTML(err.message)}</a></li>`).join("")}</ul>
        </div>`;
      summary.hidden = false;
      summary.focus();
      return;
    }
    summary.hidden = true;

    const c = findCourse(courseSel.value);
    const data = {
      code: c.code,
      name: $("#reg-name").value.trim(),
      studentId: $("#reg-id").value.trim().toUpperCase(),
      email: $("#reg-email").value.trim(),
      term: termSel.value,
      grading: $("input[name='grading']:checked", form).value,
      notes: $("#reg-notes").value.trim(),
    };

    Modal.open({
      title: "Confirm your registration",
      body: `
        <p>Please review the details below before confirming.</p>
        <dl class="summary-list">
          <dt>Course</dt><dd>${formatCode(c.code)}: ${escapeHTML(c.title)}</dd>
          <dt>Schedule</dt><dd>${formatSchedule(c)}</dd>
          <dt>Instructor</dt><dd>${escapeHTML(c.instructor)}</dd>
          <dt>Credits</dt><dd>${c.credits} (new total: ${totalCredits() + c.credits} of ${MAX_CREDITS})</dd>
          <dt>Term</dt><dd>${escapeHTML(data.term)}</dd>
          <dt>Grading</dt><dd>${escapeHTML(data.grading)}</dd>
          <dt>Student</dt><dd>${escapeHTML(data.name)} (${escapeHTML(data.studentId)})</dd>
        </dl>`,
      confirmText: "Confirm registration",
      cancelText: "Go back",
      onConfirm: () => completeRegistration(data, c),
    });
  });

  summary.addEventListener("click", (e) => {
    const link = e.target.closest("[data-focus]");
    if (!link) return;
    e.preventDefault();
    focusTargetFor(link.dataset.focus)?.focus();
  });

  function completeRegistration(data, course) {
    const regs = Store.getRegistrations();
    regs.push({
      code: data.code,
      term: data.term,
      grading: data.grading,
      notes: data.notes,
      registeredAt: new Date().toISOString(),
    });
    Store.setRegistrations(regs);

    // Keep the profile in sync with the details the student entered
    Store.setProfile({ ...Store.getProfile(), name: data.name, studentId: data.studentId, email: data.email });

    $("#success-text").innerHTML =
      `You are registered for <strong>${formatCode(course.code)}: ${escapeHTML(course.title)}</strong>
       (${escapeHTML(data.term)}). <a href="profile.html">View your profile</a> or register for another course below.`;
    success.hidden = false;
    success.focus();

    courseSel.value = "";
    $("#reg-notes").value = "";
    $("#reg-agree").checked = false;
    populateCourses();
    updatePreview();
    renderRegistrationsTable();
    updateNavBadge();
  }

  renderRegistrationsTable();
  initDropButtons(() => { populateCourses(); updatePreview(); });
}

/* ==========================================================================
   Page: Profile
   ========================================================================== */
function initProfile() {
  const form = $("#profile-form");

  function initials(name) {
    return name.split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0].toUpperCase()).join("") || "?";
  }

  function renderProfile() {
    const p = Store.getProfile();
    $("#profile-avatar").textContent = initials(p.name);
    $("#profile-name").textContent = p.name;
    $("#profile-major").textContent = `${p.major} · ${p.year}`;
    $("#pd-id").textContent = p.studentId;
    $("#pd-email").textContent = p.email;
    $("#pd-major").textContent = p.major;
    $("#pd-year").textContent = p.year;
  }

  function renderStats() {
    const regs = Store.getRegistrations();
    const credits = totalCredits(regs);
    $("#ps-courses").textContent = regs.length;
    $("#ps-credits").textContent = credits;
    $("#ps-remaining").textContent = MAX_CREDITS - credits;
    const bar = $("#credit-progress");
    bar.max = MAX_CREDITS;
    bar.value = credits;
    $("#credit-progress-text").textContent = `${credits} of ${MAX_CREDITS} credits used`;
  }

  function fillForm() {
    const p = Store.getProfile();
    $("#pf-name").value = p.name;
    $("#pf-email").value = p.email;
    $("#pf-major").value = p.major;
    $("#pf-year").value = p.year;
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    let firstInvalid = null;
    const checks = [
      ["pf-name", (v) => v.trim().length >= 2, "Enter your full name."],
      ["pf-email", (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()), "Enter a valid email address."],
      ["pf-major", (v) => v.trim().length > 0, "Enter your major."],
    ];
    checks.forEach(([id, test, msg]) => {
      const el = $(`#${id}`);
      const ok = test(el.value);
      $(`#${id}-error`).textContent = ok ? "" : msg;
      if (ok) el.removeAttribute("aria-invalid");
      else {
        el.setAttribute("aria-invalid", "true");
        firstInvalid ??= el;
      }
    });
    if (firstInvalid) { firstInvalid.focus(); return; }

    Store.setProfile({
      ...Store.getProfile(),
      name: $("#pf-name").value.trim(),
      email: $("#pf-email").value.trim(),
      major: $("#pf-major").value.trim(),
      year: $("#pf-year").value,
    });
    renderProfile();
    const msg = $("#profile-saved");
    msg.hidden = false;
    announce("Profile saved.");
  });

  form.addEventListener("input", () => { $("#profile-saved").hidden = true; });

  fillForm();
  renderProfile();
  renderStats();
  renderRegistrationsTable();
  initDropButtons(renderStats);
}

/* ==========================================================================
   Boot
   ========================================================================== */
document.addEventListener("DOMContentLoaded", () => {
  initNav();
  Modal.init();

  const pages = { home: initHome, catalog: initCatalog, register: initRegister, profile: initProfile };
  pages[document.body.dataset.page]?.();
});

