input.command:
cd /tmp/pw && npm i axe-core >/dev/null 2>&1; (cd /work && python3 -m http.server 8123 >/tmp/srv.log 2>&1 &) ; sleep 1; cat > test.js <<'EOF'
const { chromium } = require('playwright');
const axe = require('axe-core');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => m.type()==='error' && errs.push(m.text()));
  const audit = async (name) => {
    await p.addScriptTag({ content: axe.source });
    const r = await p.evaluate(() => axe.run({ runOnly: ['wcag2a','wcag2aa','wcag21aa','wcag22aa','best-practice'] }));
    console.log(name, 'axe violations:', r.violations.map(v => `${v.id}(${v.nodes.length}): ${v.nodes[0].target} ${v.nodes[0].failureSummary?.slice(0,150)}`));
  };
  const base = 'http://localhost:8123/';
  await p.goto(base + 'index.html'); await audit('home');
  console.log('depts', await p.locator('#dept-grid li').count(), 'featured', await p.locator('#featured-courses li').count());
  await p.screenshot({ path: '/tmp/pw/home.png', fullPage: true });

  await p.goto(base + 'catalog.html?q=calc'); 
  console.log('catalog q=calc:', await p.textContent('#results-count'));
  await p.fill('#search', ''); await p.selectOption('#filter-dept', 'CS'); 
  console.log('CS:', await p.textContent('#results-count'), p.url());
  await p.check('#filter-open'); console.log('CS open:', await p.textContent('#results-count'));
  await p.fill('#search', 'zzzz'); await p.waitForTimeout(500); console.log('none visible:', await p.isVisible('#no-results'));
  await audit('catalog-empty');
  await p.click('#clear-filters'); await p.waitForTimeout(50); console.log('after clear:', await p.textContent('#results-count'));
  await audit('catalog'); await p.screenshot({ path: '/tmp/pw/catalog.png', fullPage: true });

  await p.goto(base + 'register.html?course=CS340');
  console.log('preselected', await p.inputValue('#reg-course'));
  await p.uncheck('#reg-agree'); await p.fill('#reg-id', 'bad');
  await p.click('button[type=submit]');
  console.log('errors:', await p.locator('#error-summary li').allTextContents(), 'focused:', await p.evaluate(()=>document.activeElement.id));
  await audit('register-errors');
  await p.fill('#reg-id', 'S1234567'); await p.check('#reg-agree');
  await p.click('button[type=submit]');
  console.log('modal open', await p.evaluate(()=>document.querySelector('#confirm-modal').open), 'focus', await p.evaluate(()=>document.activeElement.id));
  await audit('register-modal'); await p.screenshot({ path: '/tmp/pw/modal.png' });
  await p.click('#modal-confirm');
  console.log('success visible', await p.isVisible('#success-message'), 'rows', await p.locator('#registered-tbody tr').count(), 'badge', await p.textContent('#nav-reg-count'));
  // conflict: CS101 Mon/Wed 9-10:15 vs none; MATH250 Tue/Thu 9 fine; PSY260 MWF 10-10:50 conflicts w CS101
  await p.selectOption('#reg-course', 'CS101'); await p.check('#reg-agree'); await p.click('button[type=submit]'); await p.click('#modal-confirm');
  await p.selectOption('#reg-course', 'PSY260'); await p.check('#reg-agree'); await p.click('button[type=submit]');
  console.log('conflict err:', await p.textContent('#reg-course-error'));
  await p.screenshot({ path: '/tmp/pw/register.png', fullPage: true });

  await p.goto(base + 'profile.html'); await audit('profile');
  console.log('credits', await p.textContent('#ps-credits'));
  await p.click('[data-drop="CS101"]'); await p.click('#modal-confirm');
  console.log('after drop rows', await p.locator('#registered-tbody tr').count(), 'focus', await p.evaluate(()=>document.activeElement.id));
  await p.fill('#pf-name', 'Alex <b>Kim</b>'); await p.click('#profile-form button[type=submit]');
  console.log('name', await p.textContent('#profile-name'), await p.textContent('#profile-avatar'));
  await p.screenshot({ path: '/tmp/pw/profile.png', fullPage: true });

  await p.setViewportSize({ width: 375, height: 800 });
  await p.goto(base + 'catalog.html');
  console.log('menu visible mobile', await p.isVisible('#primary-menu'));
  await p.click('.nav-toggle'); console.log('after toggle', await p.isVisible('#primary-menu'));
  await p.screenshot({ path: '/tmp/pw/mobile-menu.png' });
  await p.keyboard.press('Escape');
  await p.goto(base + 'register.html'); await p.screenshot({ path: '/tmp/pw/mobile-register.png', fullPage: true });
  const ow = await p.evaluate(()=>document.documentElement.scrollWidth); console.log('scrollWidth', ow);
  console.log('JS errors:', errs);
  await b.close();
})();
EOF
node test.js

